/**
 * Writes .env.local from the running local Supabase stack (`supabase status`).
 * Usage: npm run env:local
 */
import { execSync } from "node:child_process";
import { writeFileSync, existsSync, readFileSync } from "node:fs";
import path from "node:path";

const root = path.resolve(__dirname, "..");
const raw = execSync("npx supabase status -o json", { cwd: root, encoding: "utf8" });
const jsonStart = raw.indexOf("{");
const status = JSON.parse(raw.slice(jsonStart)) as Record<string, string>;

const lines = [
  "# Generated by scripts/write-local-env.ts — local development only. Do not commit.",
  `NEXT_PUBLIC_SUPABASE_URL=${status.API_URL}`,
  `NEXT_PUBLIC_SUPABASE_ANON_KEY=${status.ANON_KEY}`,
  "NEXT_PUBLIC_APP_URL=http://localhost:3000",
  `SUPABASE_SERVICE_ROLE_KEY=${status.SERVICE_ROLE_KEY}`,
  `DATABASE_URL=${status.DB_URL}`,
  "E2E_OWNER_EMAIL=owner@coffee.test",
  "E2E_OWNER_PASSWORD=OwnerPass123!",
  "E2E_VIEWER_EMAIL=viewer@coffee.test",
  "E2E_VIEWER_PASSWORD=ViewerPass123!",
  "E2E_INVENTORY_EMAIL=inventory@coffee.test",
  "E2E_INVENTORY_PASSWORD=InventoryPass123!",
  "",
];

const target = path.join(root, ".env.local");
if (existsSync(target)) {
  const current = readFileSync(target, "utf8");
  if (current === lines.join("\n")) {
    console.log(".env.local is up to date");
    process.exit(0);
  }
}
writeFileSync(target, lines.join("\n"));
console.log(`Wrote ${target}`);
